window.addEventListener("scroll",function(){let e=document.querySelector("header");e.classList.toggle("sticky",window.scrollY>50)}),document.querySelectorAll("nav a").forEach(e=>{e.addEventListener("click",function(e){e.preventDefault();let t=this.getAttribute("href");document.querySelector(t).scrollIntoView({behavior:"smooth"})})});let indice=0;function mudarImagem(e){let t=document.querySelectorAll(".carrossel img");t[indice].classList.remove("ativo"),t[indice=(indice+e+t.length)%t.length].classList.add("ativo")}